window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["sentry"]={html:"<div class=\"own-sentry\">\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"sy-nav\">\n    <a class=\"sy-brand\" href=\"#sy-top\"><span class=\"sy-brand-mark\" aria-hidden=\"true\"></span>Northwind</a>\n    <nav class=\"sy-nav-links\" aria-label=\"Primary\">\n      <a href=\"#sy-features\">Product</a>\n      <a href=\"#sy-code\">Developers</a>\n      <a href=\"#sy-pricing\">Pricing</a>\n      <a href=\"#sy-customers\">Customers</a>\n    </nav>\n    <div class=\"sy-nav-right\">\n      <a class=\"sy-ghost\" href=\"#\">Get demo</a>\n      <a class=\"sy-btn sy-btn-invert\" href=\"#sy-pricing\">Get started</a>\n    </div>\n  </header>\n\n  <main id=\"sy-top\">\n    <!-- ── HERO (dark canvas) ────────────────────────────────────────── -->\n    <section class=\"sy-hero\">\n      <div class=\"sy-stars\" aria-hidden=\"true\"></div>\n      <span class=\"sy-mascot sy-mascot-a\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 100\"><circle cx=\"50\" cy=\"44\" r=\"26\" fill=\"#fa7faa\"/><circle cx=\"50\" cy=\"44\" r=\"26\" fill=\"none\" stroke=\"#150f23\" stroke-width=\"3\"/><circle cx=\"41\" cy=\"40\" r=\"4\" fill=\"#150f23\"/><circle cx=\"59\" cy=\"40\" r=\"4\" fill=\"#150f23\"/><path d=\"M40 54c6 6 14 6 20 0\" stroke=\"#150f23\" stroke-width=\"3\" fill=\"none\" stroke-linecap=\"round\"/><path d=\"M28 24l8 10M72 24l-8 10\" stroke=\"#150f23\" stroke-width=\"3\" stroke-linecap=\"round\"/></svg></span>\n      <span class=\"sy-mascot sy-mascot-b\" aria-hidden=\"true\"><svg viewBox=\"0 0 100 100\"><path d=\"M50 12 60 40l30 2-24 18 9 30-25-17-25 17 9-30-24-18 30-2z\" fill=\"#c2ef4e\" stroke=\"#150f23\" stroke-width=\"3\" stroke-linejoin=\"round\"/></svg></span>\n      <div class=\"sy-hero-inner\">\n        <p class=\"sy-eyebrow\">Operations observability</p>\n        <h1 class=\"sy-display\">Ship reliable operations <span class=\"sy-lime\">without guesswork.</span></h1>\n        <p class=\"sy-lead\">Northwind traces every dashboard, pipeline, and region in one place, so you can find the slow query <span class=\"sy-link\">before it pages you</span> at 3am.</p>\n        <div class=\"sy-hero-cta\">\n          <a class=\"sy-btn sy-btn-invert\" href=\"#sy-pricing\">Start for free</a>\n          <a class=\"sy-ghost sy-ghost-dark\" href=\"#sy-code\">Read the docs</a>\n        </div>\n        <p class=\"sy-hero-note\">No credit card required</p>\n      </div>\n    </section>\n\n    <!-- ── FEATURE BAND (dark) ───────────────────────────────────────── -->\n    <section id=\"sy-features\" class=\"sy-band\">\n      <p class=\"sy-eyebrow\">What you get</p>\n      <h2 class=\"sy-display-lg\">Everything, <span class=\"sy-lime\">in one console.</span></h2>\n      <div class=\"sy-grid\" id=\"syFeatureGrid\"></div>\n    </section>\n\n    <!-- ── CODE BLOCK (dark) ─────────────────────────────────────────── -->\n    <section id=\"sy-code\" class=\"sy-split\">\n      <div class=\"sy-split-copy\">\n        <p class=\"sy-eyebrow\">Instrument in minutes</p>\n        <h2 class=\"sy-display-lg\">Add the SDK.<br>See the whole floor.</h2>\n        <p class=\"sy-body\">Drop the client into your pipeline, point it at a project, and Northwind starts grouping throughput regressions the moment they appear.</p>\n        <a class=\"sy-link sy-body\" href=\"#\">Read the quickstart &rarr;</a>\n      </div>\n      <div class=\"sy-codeblock\">\n        <div class=\"sy-codebar\"><span class=\"sy-cd\"></span><span class=\"sy-cd\"></span><span class=\"sy-cd\"></span><span class=\"sy-codetab\">pipeline.js</span></div>\n        <pre class=\"sy-code\"><span class=\"sy-c-key\">import</span> * <span class=\"sy-c-key\">as</span> NW <span class=\"sy-c-key\">from</span> <span class=\"sy-c-str\">'@northwind/node'</span>;\n\nNW.<span class=\"sy-c-name\">init</span>({\n  <span class=\"sy-c-key\">project</span>: <span class=\"sy-c-str\">'ops-analytics'</span>,\n  <span class=\"sy-c-key\">region</span>: <span class=\"sy-c-str\">'luzon'</span>,\n  <span class=\"sy-c-key\">tracesSampleRate</span>: <span class=\"sy-c-num\">0.25</span>\n});\n\n<span class=\"sy-c-com\">// group regressions by region</span>\nNW.<span class=\"sy-c-name\">captureIssue</span>(<span class=\"sy-c-str\">'throughput-drop'</span>);</pre>\n      </div>\n    </section>\n\n    <!-- ── SPOTLIGHT (deep violet card) ──────────────────────────────── -->\n    <section class=\"sy-band\">\n      <div class=\"sy-spotlight\">\n        <div class=\"sy-spotlight-copy\">\n          <span class=\"sy-chip\">Northwind only</span>\n          <h2 class=\"sy-display-lg\">Forecast where the floor will slow down.</h2>\n          <p class=\"sy-body\">Northwind correlates throughput trend lines with deploy history and flags the regions most likely to miss target — before the number lands.</p>\n        </div>\n        <div class=\"sy-spotlight-art\" aria-hidden=\"true\">\n          <div class=\"sy-spark\"><span style=\"--h:40%\"></span><span style=\"--h:58%\"></span><span style=\"--h:36%\"></span><span style=\"--h:72%\"></span><span style=\"--h:52%\"></span><span style=\"--h:88%\"></span></div>\n          <span class=\"sy-spark-label\">forecast · +14% variance</span>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── PRICING (light canvas) ────────────────────────────────────── -->\n    <section id=\"sy-pricing\" class=\"sy-pricing\">\n      <p class=\"sy-eyebrow sy-on-light\">Pricing</p>\n      <h2 class=\"sy-display-lg sy-on-light\">Plans for dev teams of every size.</h2>\n      <div class=\"sy-tiers\" id=\"syTierGrid\"></div>\n      <p class=\"sy-fine sy-on-light\">All plans include the query API, 30-day retention, and unlimited projects.</p>\n    </section>\n\n    <!-- ── CUSTOMERS ─────────────────────────────────────────────────── -->\n    <section id=\"sy-customers\" class=\"sy-band sy-quote-band\">\n      <div class=\"sy-quote\">\n        <p class=\"sy-quote-text\">“We went from firefighting throughput alerts to shipping a fix before the standup. Northwind is the first console our analysts actually open.”</p>\n        <p class=\"sy-quote-by\">Dane Ocampo &middot; Head of Operations, Northfork</p>\n      </div>\n      <div class=\"sy-logo-wall\" aria-label=\"Customers\">\n        <span>ATLAS</span><span>KESTREL</span><span>HELIOS</span><span>MERIDIAN</span><span>BLUEPRINT</span>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ──────────────────────────────────────────────────────── -->\n  <footer class=\"sy-footer\">\n    <svg class=\"sy-squiggle\" viewBox=\"0 0 1200 16\" preserveAspectRatio=\"none\" aria-hidden=\"true\"><path d=\"M0 8c60-12 120 12 180 0s120-12 180 0 120 12 180 0 120-12 180 0 120 12 180 0 120-12 180 0\" fill=\"none\" stroke=\"#c2ef4e\" stroke-width=\"3\"/></svg>\n    <div class=\"sy-foot-grid\">\n      <div class=\"sy-foot-brand\">\n        <span class=\"sy-brand sy-on-light\"><span class=\"sy-brand-mark\" aria-hidden=\"true\"></span>Northwind</span>\n        <p class=\"sy-body sy-on-light-mute\">Observability for operations teams that live in the terminal.</p>\n      </div>\n      <div class=\"sy-foot-col\"><h3>Product</h3><a href=\"#\">Overview</a><a href=\"#\">Forecasting</a><a href=\"#\">Query API</a></div>\n      <div class=\"sy-foot-col\"><h3>Developers</h3><a href=\"#\">Docs</a><a href=\"#\">SDK</a><a href=\"#\">Changelog</a></div>\n      <div class=\"sy-foot-col\"><h3>Company</h3><a href=\"#\">About</a><a href=\"#\">Careers</a><a href=\"#\">Contact</a></div>\n    </div>\n    <div class=\"sy-foot-row\"><span>Sample data — showcase only</span><span>© 2026 Northwind</span></div>\n  </footer>\n</div>\n",css:"/* ══ SENTRY — own layout for showcase.html ═══════════════════════════════\n   Deep violet midnight canvas with starfield texture and sticker mascots,\n   electric-lime keyword chips as a typographic device, Rubik UI copy, caps\n   buttons with 0.2px tracking, and a dark-inverted featured pricing tier.\n   Scoped under `.own-sentry`. */\n\n.own-sentry {\n  --primary: #150f23;\n  --ink-deep: #1f1633;\n  --night: #150f23;\n  --canvas-dark: #1f1633;\n  --canvas-light: #ffffff;\n  --lime: #c2ef4e;\n  --pink: #fa7faa;\n  --violet: #6a5fc1;\n  --violet-deep: #422082;\n  --violet-mid: #79628c;\n  --hairline-violet: #362d59;\n  --hairline-cool: #cfcfdb;\n  --hairline-cloud: #e5e7eb;\n  --ink: #1f1633;\n  --ink-press: #1a1a1a;\n  --on-dark-muted: #bdb8c0;\n  --on-dark-faint: rgba(255, 255, 255, .18);\n  --focus: #9dc1f5;\n\n  --f-display: 'Space Grotesk', 'Rubik', system-ui, sans-serif;\n  --f-ui: 'Rubik', -apple-system, system-ui, 'Segoe UI', Helvetica, Arial, sans-serif;\n  --f-code: 'Monaco', 'Menlo', 'Ubuntu Mono', monospace;\n\n  --gut: clamp(20px, 4.4cqi, 56px);\n  --sec: clamp(56px, 9cqi, 96px);\n\n  position: relative;\n  border-radius: 13px;\n  background: var(--canvas-dark);\n  color: #fff;\n  font-family: var(--f-ui);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n.own-sentry *, .own-sentry *::before, .own-sentry *::after { box-sizing: border-box; }\n.own-sentry :focus-visible { outline: 3px solid var(--focus); outline-offset: 3px; border-radius: 6px; }\n.own-sentry .sy-on-light { color: var(--ink-deep); }\n.own-sentry .sy-on-light-mute { color: rgba(31, 22, 51, .7); }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-sentry .sy-eyebrow {\n  font-size: 15px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.2px;\n  color: var(--on-dark-muted); margin: 0 0 20px;\n}\n.own-sentry .sy-display {\n  font-family: var(--f-display); font-weight: 700;\n  font-size: clamp(42px, 7cqi, 88px); line-height: 1.2; letter-spacing: -0.02em;\n  margin: 0; max-width: 15ch;\n}\n.own-sentry .sy-display-lg {\n  font-family: var(--f-display); font-weight: 500;\n  font-size: clamp(30px, 4.4cqi, 60px); line-height: 1.1; letter-spacing: -0.01em; margin: 0 0 22px;\n}\n.own-sentry .sy-lead { margin: 24px 0 30px; max-width: 52ch; color: var(--on-dark-muted); font-size: 16px; line-height: 2; }\n.own-sentry .sy-body { color: var(--on-dark-muted); font-size: 16px; line-height: 2; max-width: 60ch; }\n.own-sentry .sy-fine { color: var(--on-dark-muted); font-size: 14px; margin-top: 24px; }\n.own-sentry .sy-lime {\n  background: var(--lime); color: var(--ink-deep);\n  border-radius: 4px; padding: 0 12px; display: inline-block;\n}\n.own-sentry .sy-chip {\n  display: inline-block; background: var(--lime); color: var(--ink-deep);\n  font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.25px;\n  padding: 4px 10px; border-radius: 4px; margin-bottom: 18px;\n}\n.own-sentry .sy-link { color: #fff; text-decoration: underline; text-underline-offset: 3px; }\n.own-sentry .sy-link:hover { color: var(--lime); }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-sentry .sy-btn {\n  display: inline-flex; align-items: center; justify-content: center;\n  height: 44px; padding: 0 16px;\n  font-family: var(--f-ui); font-size: 14px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.2px;\n  border-radius: 8px; transition: background-color .18s, color .18s, transform .18s;\n}\n.own-sentry .sy-btn-invert { background: #fff; color: var(--ink-deep); }\n.own-sentry .sy-btn-invert:hover { background: #f0f0f0; color: var(--ink-press); }\n.own-sentry .sy-btn-primary { background: var(--primary); color: #fff; }\n.own-sentry .sy-btn-primary:hover { background: #fff; color: var(--ink-deep); }\n.own-sentry .sy-ghost {\n  display: inline-flex; align-items: center; height: 44px; padding: 0 16px;\n  font-size: 14px; font-weight: 500; text-transform: uppercase; letter-spacing: 0.2px;\n  border-radius: 12px; color: #fff; transition: background-color .18s;\n}\n.own-sentry .sy-ghost-dark { background: var(--on-dark-faint); border: none; }\n.own-sentry .sy-ghost-dark:hover { background: rgba(255, 255, 255, .28); }\n.own-sentry .sy-ghost:not(.sy-ghost-dark) { border: 1px solid transparent; }\n.own-sentry .sy-ghost:not(.sy-ghost-dark):hover { background: var(--on-dark-faint); }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-sentry .sy-nav {\n  position: sticky; top: 68px; z-index: 40;\n  display: flex; align-items: center; gap: 26px;\n  height: 64px; padding: 0 var(--gut);\n  background: rgba(31, 22, 51, .86); backdrop-filter: blur(10px);\n}\n.own-sentry .sy-brand {\n  display: inline-flex; align-items: center; gap: 9px;\n  font-family: var(--f-display); font-weight: 700; font-size: 20px; letter-spacing: -0.01em; color: #fff;\n}\n.own-sentry .sy-brand-mark { width: 16px; height: 16px; border-radius: 4px; background: var(--lime); }\n.own-sentry .sy-nav-links { display: flex; align-items: center; gap: 22px; font-size: 16px; font-weight: 500; }\n.own-sentry .sy-nav-links a { color: var(--on-dark-muted); transition: color .18s; }\n.own-sentry .sy-nav-links a:hover { color: #fff; }\n.own-sentry .sy-nav-right { margin-left: auto; display: flex; align-items: center; gap: 10px; }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-sentry .sy-hero {\n  position: relative; overflow: hidden; isolation: isolate;\n  padding: clamp(64px, 11cqi, 150px) var(--gut) clamp(64px, 9cqi, 120px);\n  background: radial-gradient(120% 90% at 78% 0%, #2a1c46 0%, var(--canvas-dark) 52%, var(--night) 100%);\n}\n.own-sentry .sy-stars {\n  position: absolute; inset: 0; z-index: -1; opacity: .5;\n  background-image: radial-gradient(rgba(255,255,255,.55) 1px, transparent 1px), radial-gradient(rgba(194,239,78,.4) 1px, transparent 1px);\n  background-size: 84px 84px, 140px 140px; background-position: 0 0, 40px 60px;\n}\n.own-sentry .sy-hero-inner { position: relative; max-width: 860px; }\n.own-sentry .sy-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }\n.own-sentry .sy-hero-note { margin: 20px 0 0; font-size: 14px; color: var(--on-dark-muted); }\n.own-sentry .sy-mascot { position: absolute; width: clamp(58px, 7cqi, 96px); height: auto; z-index: 0; }\n.own-sentry .sy-mascot svg { width: 100%; height: 100%; display: block; }\n.own-sentry .sy-mascot-a { right: clamp(16px, 8cqi, 120px); top: clamp(70px, 12cqi, 150px); transform: rotate(-8deg); animation: sy-float 6s ease-in-out infinite; }\n.own-sentry .sy-mascot-b { right: clamp(60px, 18cqi, 240px); bottom: clamp(20px, 5cqi, 70px); width: clamp(40px, 5cqi, 66px); transform: rotate(10deg); animation: sy-float 7.5s ease-in-out infinite reverse; }\n@keyframes sy-float { 0%,100% { translate: 0 0; } 50% { translate: 0 -12px; } }\n\n/* ── dark band ───────────────────────────────────────────────────────── */\n.own-sentry .sy-band { padding: var(--sec) var(--gut) 0; }\n.own-sentry .sy-grid { display: grid; grid-template-columns: 1fr 1fr; gap: 18px; margin-top: 44px; }\n.own-sentry .sy-card {\n  background: var(--ink-deep); border: 1px solid var(--hairline-violet);\n  border-radius: 18px; padding: 32px;\n}\n.own-sentry .sy-card h3 { font-family: var(--f-display); font-weight: 500; font-size: 27px; line-height: 1.1; margin: 0 0 12px; }\n.own-sentry .sy-card p { color: var(--on-dark-muted); font-size: 16px; line-height: 2; margin: 0; }\n.own-sentry .sy-card-art { margin-top: 24px; border-top: 1px solid var(--hairline-violet); padding-top: 20px; }\n.own-sentry .sy-card-art svg { width: 100%; height: 60px; }\n\n/* ── code split ──────────────────────────────────────────────────────── */\n.own-sentry .sy-split {\n  padding: var(--sec) var(--gut) 0;\n  display: grid; grid-template-columns: 1fr 1.15fr; gap: clamp(28px, 4cqi, 56px); align-items: center;\n}\n.own-sentry .sy-split .sy-link { display: inline-block; margin-top: 8px; font-size: 16px; font-weight: 500; }\n.own-sentry .sy-codeblock { background: var(--night); border: 1px solid var(--hairline-violet); border-radius: 8px; overflow: hidden; }\n.own-sentry .sy-codebar { display: flex; align-items: center; gap: 7px; padding: 12px 16px; border-bottom: 1px solid var(--hairline-violet); }\n.own-sentry .sy-cd { width: 10px; height: 10px; border-radius: 50%; background: var(--hairline-violet); }\n.own-sentry .sy-codetab { margin-left: 8px; font-family: var(--f-code); font-size: 12px; color: var(--on-dark-muted); }\n.own-sentry .sy-code { margin: 0; padding: 22px; font-family: var(--f-code); font-size: 14px; line-height: 1.7; color: #e6e2ee; white-space: pre; overflow-x: auto; }\n.own-sentry .sy-c-key { color: var(--pink); }\n.own-sentry .sy-c-name { color: var(--lime); }\n.own-sentry .sy-c-str { color: #a7c9ff; }\n.own-sentry .sy-c-num { color: #ffcf7a; }\n.own-sentry .sy-c-com { color: var(--on-dark-muted); }\n\n/* ── spotlight ───────────────────────────────────────────────────────── */\n.own-sentry .sy-spotlight {\n  display: grid; grid-template-columns: 1.15fr .85fr; gap: clamp(24px, 3cqi, 44px); align-items: center;\n  background: var(--violet-deep); border-radius: 18px; padding: clamp(28px, 4cqi, 56px);\n}\n.own-sentry .sy-spotlight-art { background: rgba(21,15,35,.4); border: 1px solid rgba(255,255,255,.14); border-radius: 12px; padding: 22px; }\n.own-sentry .sy-spark { display: flex; align-items: flex-end; gap: clamp(6px, 1.4cqi, 16px); height: 130px; }\n.own-sentry .sy-spark span { flex: 1; height: var(--h); background: var(--lime); border-radius: 3px 3px 0 0; }\n.own-sentry .sy-spark span:nth-child(4), .own-sentry .sy-spark span:nth-child(6) { background: var(--pink); }\n.own-sentry .sy-spark-label { display: block; margin-top: 14px; font-family: var(--f-code); font-size: 12px; color: var(--on-dark-muted); }\n\n/* ── pricing (light canvas) ──────────────────────────────────────────── */\n.own-sentry .sy-pricing { margin-top: var(--sec); padding: var(--sec) var(--gut); background: var(--canvas-light); color: var(--ink-deep); }\n.own-sentry .sy-pricing .sy-eyebrow { color: rgba(31,22,51,.6); }\n.own-sentry .sy-tiers { display: grid; grid-template-columns: repeat(4, 1fr); gap: 18px; margin-top: 44px; }\n.own-sentry .sy-tier {\n  background: #fff; border: 1px solid var(--hairline-cloud); border-radius: 12px;\n  padding: 32px; display: flex; flex-direction: column; gap: 14px; color: var(--ink-deep);\n}\n.own-sentry .sy-tier-name { font-family: var(--f-ui); font-weight: 600; font-size: 20px; }\n.own-sentry .sy-tier-price { font-family: var(--f-display); font-weight: 500; font-size: 48px; line-height: 1.1; letter-spacing: -0.01em; }\n.own-sentry .sy-tier-price small { font-size: 15px; color: rgba(31,22,51,.55); font-family: var(--f-ui); font-weight: 400; }\n.own-sentry .sy-tier-list { list-style: none; margin: 6px 0 18px; padding: 0; display: grid; gap: 10px; font-size: 15px; color: rgba(31,22,51,.78); }\n.own-sentry .sy-tier-list li::before { content: '—'; margin-right: 8px; color: var(--violet); }\n.own-sentry .sy-tier .sy-btn { margin-top: auto; width: 100%; }\n.own-sentry .sy-tier-feat { background: var(--night); border-color: var(--hairline-violet); color: #fff; }\n.own-sentry .sy-tier-feat .sy-tier-price small, .own-sentry .sy-tier-feat .sy-tier-list { color: var(--on-dark-muted); }\n.own-sentry .sy-tier-feat .sy-tier-list li::before { color: var(--lime); }\n.own-sentry .sy-tier-feat .sy-btn-primary { background: #fff; color: var(--ink-deep); }\n.own-sentry .sy-tier-feat .sy-btn-primary:hover { background: var(--lime); }\n.own-sentry .sy-tier-badge { align-self: flex-start; font-size: 10px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.25px; background: var(--lime); color: var(--ink-deep); padding: 4px 8px; border-radius: 4px; }\n\n/* ── quote / logos ───────────────────────────────────────────────────── */\n.own-sentry .sy-quote-band { padding-bottom: 0; }\n.own-sentry .sy-quote { max-width: 780px; }\n.own-sentry .sy-quote-text { font-family: var(--f-display); font-weight: 500; font-size: clamp(24px, 3cqi, 40px); line-height: 1.3; margin: 0 0 18px; }\n.own-sentry .sy-quote-by { color: var(--on-dark-muted); font-size: 15px; }\n.own-sentry .sy-logo-wall { display: flex; flex-wrap: wrap; gap: clamp(22px, 5cqi, 64px); margin-top: 54px; padding-top: 34px; border-top: 1px solid var(--hairline-violet); }\n.own-sentry .sy-logo-wall span { font-family: var(--f-display); font-weight: 700; font-size: clamp(16px, 1.7cqi, 22px); letter-spacing: 0.08em; color: var(--on-dark-muted); }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-sentry .sy-footer { background: var(--canvas-light); color: var(--ink-deep); padding: clamp(40px, 5cqi, 64px) var(--gut) 32px; }\n.own-sentry .sy-squiggle { display: block; width: 100%; height: 16px; margin-bottom: 40px; }\n.own-sentry .sy-foot-grid { display: grid; grid-template-columns: 1.4fr repeat(3, 1fr); gap: 32px; }\n.own-sentry .sy-foot-brand .sy-brand { margin-bottom: 14px; color: var(--ink-deep); }\n.own-sentry .sy-foot-col { display: flex; flex-direction: column; gap: 12px; }\n.own-sentry .sy-foot-col h3 { margin: 0 0 4px; font-size: 13px; font-weight: 600; text-transform: uppercase; letter-spacing: 0.2px; }\n.own-sentry .sy-foot-col a { color: rgba(31,22,51,.72); font-size: 15px; }\n.own-sentry .sy-foot-col a:hover { color: var(--violet); }\n.own-sentry .sy-foot-row { display: flex; justify-content: space-between; gap: 16px; flex-wrap: wrap; margin-top: 40px; padding-top: 22px; border-top: 1px solid var(--hairline-cloud); font-size: 14px; color: rgba(31,22,51,.6); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-sentry .sy-split { grid-template-columns: 1fr; }\n  .own-sentry .sy-spotlight { grid-template-columns: 1fr; }\n  .own-sentry .sy-tiers { grid-template-columns: 1fr 1fr; }\n  .own-sentry .sy-foot-grid { grid-template-columns: 1fr 1fr; }\n}\n@container frame (max-width: 760px) {\n  .own-sentry .sy-nav-links { display: none; }\n  .own-sentry .sy-grid { grid-template-columns: 1fr; }\n  .own-sentry .sy-mascot-a { display: none; }\n  .own-sentry .sy-display { font-size: clamp(38px, 12cqi, 54px); }\n}\n@container frame (max-width: 430px) {\n  .own-sentry .sy-nav-right .sy-ghost { display: none; }\n  .own-sentry .sy-tiers { grid-template-columns: 1fr; }\n  .own-sentry .sy-mascot-b { display: none; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-sentry *, .own-sentry *::before, .own-sentry *::after { animation-duration: .001ms !important; transition-duration: .001ms !important; }\n  .own-sentry .sy-mascot { animation: none; }\n}\n"};
/* ══ SENTRY — own layout behaviour for showcase.html ═════════════════════
   Registers window.OWN_LAYOUTS['sentry'].init(root). Renders the feature
   grid and pricing tiers from data. Returns a cleanup fn. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  var FEATURES = [
    {
      title: 'Issue grouping',
      body: 'Northwind clusters throughput regressions by cause, region, and pipeline so one alert stands in for a thousand.',
      art: '<svg viewBox="0 0 280 60" fill="none" aria-hidden="true"><path d="M4 46 40 30l34 10 40-24 36 16 44-22 46 18 36-12" stroke="#c2ef4e" stroke-width="2.5" stroke-linecap="round" stroke-linejoin="round"/><circle cx="154" cy="32" r="5" fill="#fa7faa"/></svg>'
    },
    {
      title: 'Live dashboards',
      body: 'Pin the metrics your floor cares about — throughput, yield, cost per case — and share a board with one link.',
      art: '<svg viewBox="0 0 280 60" fill="none" aria-hidden="true"><rect x="6" y="14" width="70" height="36" rx="4" stroke="#79628c"/><rect x="88" y="14" width="70" height="36" rx="4" stroke="#79628c"/><rect x="170" y="14" width="70" height="36" rx="4" stroke="#c2ef4e"/></svg>'
    },
    {
      title: 'Deploy tracking',
      body: 'Every change is stamped to the release that shipped it, so you can trace a regression back to a commit.',
      art: '<svg viewBox="0 0 280 60" fill="none" aria-hidden="true"><circle cx="24" cy="30" r="8" stroke="#79628c"/><circle cx="110" cy="30" r="8" stroke="#c2ef4e"/><circle cx="196" cy="30" r="8" stroke="#79628c"/><circle cx="262" cy="30" r="6" stroke="#79628c"/><path d="M32 30h70M118 30h70M204 30h50" stroke="#79628c"/></svg>'
    },
    {
      title: 'Alert routing',
      body: 'Send the right alert to the right on-call, with rules that match the region and severity of the miss.',
      art: '<svg viewBox="0 0 280 60" fill="none" aria-hidden="true"><path d="M20 30h60l40-16 40 32 40-16 60 0" stroke="#fa7faa" stroke-width="2" stroke-linejoin="round" stroke-linecap="round"/></svg>'
    }
  ];

  var TIERS = [
    {
      name: 'Developer', price: '$0', unit: '/mo',
      feats: ['5k events / month', '30-day retention', 'Community support'],
      cta: 'Start free', feat: false
    },
    {
      name: 'Team', price: '$29', unit: '/mo',
      feats: ['100k events / month', '90-day retention', 'Forecasting alerts'],
      cta: 'Start trial', feat: false
    },
    {
      name: 'Business', price: '$89', unit: '/mo', badge: 'Most popular',
      feats: ['2M events / month', '1-year retention', 'SSO + audit log', 'Priority support'],
      cta: 'Get started', feat: true
    },
    {
      name: 'Enterprise', price: "Let's talk", unit: '',
      feats: ['Volume pricing', 'On-prem option', 'Dedicated engineer'],
      cta: 'Contact sales', feat: false
    }
  ];

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  OWN['sentry'] = {
    init: function (root) {
      var reduced = false;
      try { reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches; } catch (e) { /* ignore */ }

      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var disposed = false;
      var observers = [];
      var rafs = [];

      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }
      function raf(fn) { var id = requestAnimationFrame(fn); rafs.push(id); return id; }
      function $(sel) { return root.querySelector(sel); }

      var grid = $('#syFeatureGrid');
      if (grid) grid.innerHTML = FEATURES.map(function (f) {
        return '<article class="sy-card"><h3>' + esc(f.title) + '</h3><p>' + esc(f.body) + '</p>'
          + '<div class="sy-card-art">' + f.art + '</div></article>';
      }).join('');

      var tiers = $('#syTierGrid');
      if (tiers) tiers.innerHTML = TIERS.map(function (t) {
        return '<div class="sy-tier' + (t.feat ? ' sy-tier-feat' : '') + '">'
          + (t.badge ? '<span class="sy-tier-badge">' + esc(t.badge) + '</span>' : '')
          + '<span class="sy-tier-name">' + esc(t.name) + '</span>'
          + '<span class="sy-tier-price">' + esc(t.price) + (t.unit ? ' <small>' + esc(t.unit) + '</small>' : '') + '</span>'
          + '<ul class="sy-tier-list">' + t.feats.map(function (x) { return '<li>' + esc(x) + '</li>'; }).join('') + '</ul>'
          + '<a class="sy-btn ' + (t.feat ? 'sy-btn-primary' : 'sy-btn-primary') + '" href="#">' + esc(t.cta) + '</a>'
          + '</div>';
      }).join('');

      function animateSpark() {
        var bars = Array.prototype.slice.call(root.querySelectorAll('.sy-spark span'));
        if (!bars.length || reduced) return;
        bars.forEach(function (b, i) {
          var target = b.style.getPropertyValue('--h') || '50%';
          b.style.height = '8%';
          b.style.transition = 'height .6s cubic-bezier(.16,1,.3,1)';
          setTimeout(function () { if (!disposed) b.style.height = target; }, 80 + i * 70);
        });
      }

      var io = null;
      if (typeof IntersectionObserver !== 'undefined') {
        io = new IntersectionObserver(function (ents) {
          ents.forEach(function (en) {
            if (en.isIntersecting) { animateSpark(); io.unobserve(en.target); }
          });
        }, { threshold: 0.2 });
        var spark = $('.sy-spark');
        if (spark) { observers.push(io); io.observe(spark); }
      } else {
        animateSpark();
      }

      return function cleanup() {
        disposed = true;
        if (AC) { try { AC.abort(); } catch (e) { /* ignore */ } }
        rafs.forEach(function (id) { cancelAnimationFrame(id); });
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) { /* ignore */ } });
      };
    }
  };
})();
